  MaterialButton yes=button("批准",()->decide(result.optString("approval_token"),true,controls,heading));MaterialButton no=button("拒绝",()->decide(result.optString("approval_token"),false,controls,heading));controls.addView(yes,new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(no,new LinearLayout.LayoutParams(0,dp(48),1));messages.addView(card);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));
