 private void attachDocument(Uri uri)throws Exception{
  String name="附件";
  try(android.database.Cursor cursor=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}
  if(name==null||!name.toLowerCase(Locale.ROOT).matches(".*\\.(txt|md|markdown|csv|ics|json|html|htm)$"))throw new IOException("请选择文本文件（TXT、MD、CSV、ICS、JSON 或 HTML）；PDF / Office 请先转为文本或图片");
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();
  try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("文件不可读");byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(bytes.size()+n>256*1024)throw new IOException("单个文本文件最多256KB");bytes.write(block,0,n);}}
  String text=java.nio.charset.StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();
  String label=name;
  runOnUiThread(()->{if(!closed){pendingDocuments.add("<附件 name=\""+label.replace("\"", "")+"\">\n"+text+"\n</附件>");pendingDocumentNames.add(label);renderAttachments();}});
 }
 private void attachImage(Uri uri)throws Exception{
  String mime=getContentResolver().getType(uri);
  if(mime==null||!mime.startsWith("image/"))throw new IOException("无法确定图片格式，请选择图片文件");
  String extension=android.webkit.MimeTypeMap.getSingleton().getExtensionFromMimeType(mime);
  if(extension==null||!extension.matches("[a-z0-9]+"))extension="img";
  File imageDir=new File(getCacheDir(),"assistant-images");if(!imageDir.isDirectory()&&!imageDir.mkdirs())throw new IOException("无法创建附件目录");
  String filename=UUID.randomUUID()+"."+extension;File file=new File(imageDir,filename);
  try{
   try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("图片不可读");byte[] block=new byte[32768];int n;while((n=in.read(block))!=-1){if(closed)throw new IOException("附件处理已取消");out.write(block,0,n);}}
   String dataUrl="data:"+mime+";base64,"+Base64.encodeToString(java.nio.file.Files.readAllBytes(file.toPath()),Base64.NO_WRAP);
   BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),opt);int sample=1;while(Math.max(opt.outWidth,opt.outHeight)/sample>256)sample*=2;opt.inJustDecodeBounds=false;opt.inSampleSize=sample;
   Bitmap preview=BitmapFactory.decodeFile(file.getPath(),opt);
   runOnUiThread(()->{if(closed){if(preview!=null)preview.recycle();return;}pendingImages.add(dataUrl);pendingImageFiles.add(filename);attachmentPreview.setImageBitmap(preview);renderAttachments();});
  }catch(OutOfMemoryError e){file.delete();throw new IOException("原图超过设备可用内存，请分批发送；图片未压缩",e);}catch(Exception e){file.delete();throw e;}
 }

 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==4&&result==RESULT_OK&&data!=null){input.setText(data.getStringExtra("voice_text"));input.setSelection(input.length());return;}if((code==3||code==5)&&result==RESULT_OK&&data!=null){
  ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());

  setBusy(true,"正在处理附件…");worker.execute(()->{try{for(Uri uri:uris){if(closed)break;if(code==3)attachImage(uri);else attachDocument(uri);}}catch(Exception e){showError(e);}finally{runOnUiThread(()->{if(!closed)setBusy(false,"");});}});return;}if(code==2&&result==RESULT_OK&&data!=null){ArrayList<String> values=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(values!=null&&!values.isEmpty()){input.setText(values.get(0));input.setSelection(input.length());}}}
 private void setBusy(boolean value,String label){busy=value;send.setEnabled(!value);voice.setEnabled(!value);image.setEnabled(!value);undo.setEnabled(!value);status.setText(label);}
 private void showError(Exception e){if(getApplication() instanceof ConversationAppearance appearance)appearance.recordConversationError("assistant-chat",e);runOnUiThread(()->{if(!closed)bubble("未完成",(e.getMessage()==null?"请求失败":e.getMessage())+"\n已经成功创建的事项保留，请核对结果后再重试。");});}
 private void bubble(String who,String value){bubble(who,value,null);}
 private void bubble(String who,String value,String imageFile){try{transcript.put(new JSONObject().put("who",who).put("text",value).put("image",imageFile==null?"":imageFile));while(transcript.length()>80)transcript.remove(0);}catch(Exception ignored){}addBubble(who,value,imageFile);}
 private void addBubble(String who,String value){addBubble(who,value,null);}
 private void addBubble(String who,String value,String imageFile){boolean mine=who.equals("你");LinearLayout line=row();line.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);line.setPadding(mine?dp(36):0,dp(6),mine?0:dp(36),dp(6));LinearLayout bubble=column();bubble.setPadding(dp(getIntent().getBooleanExtra("dayflow_compact",false)?14:20),dp(getIntent().getBooleanExtra("dayflow_compact",false)?8:12),dp(getIntent().getBooleanExtra("dayflow_compact",false)?14:20),dp(getIntent().getBooleanExtra("dayflow_compact",false)?16:24));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();int fill=color(mine?com.google.android.material.R.attr.colorSecondaryContainer:com.google.android.material.R.attr.colorSurfaceContainerLow);
 bg.setColor((fill&0x00ffffff)|0xea000000);bg.setCornerRadius(dp(18));
 bg.setStroke(dp(1),(color(com.google.android.material.R.attr.colorOutlineVariant)&0x00ffffff)|0x60000000);bubble.setBackground(bg);if(getApplication() instanceof ConversationAppearance appearance)appearance.styleConversationSurface(bubble,mine);if(!mine&&!who.equals("助手")){TextView label=text(who,11);label.setAlpha(.65f);bubble.addView(label);}if(imageFile!=null)for(String filename:imageFile.split(",")){if(!filename.matches("[a-f0-9-]+\\.[a-z0-9]+"))continue;File file=new File(getCacheDir(),"assistant-images/"+filename);if(file.isFile()){ImageView imageView=new ImageView(this);imageView.setScaleType(ImageView.ScaleType.CENTER_CROP);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),opt);opt.inSampleSize=1;while(Math.max(opt.outWidth,opt.outHeight)/opt.inSampleSize>320)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;imageView.setImageBitmap(BitmapFactory.decodeFile(file.getPath(),opt));imageView.setContentDescription("点击预览已发送图片");imageView.setOnClickListener(v->PhotoPreview.show(this,file));bubble.addView(imageView,new LinearLayout.LayoutParams(dp(160),dp(160)));}}

 if(!value.isEmpty()){TextView body=text("",getIntent().getIntExtra("dayflow_font_size",17));body.setMaxWidth(Math.max(dp(160),getResources().getDisplayMetrics().widthPixels-dp(110)));body.setTextIsSelectable(true);body.setLineSpacing(0,1.06f);Markdown.render(body,value);bubble.addView(body,new LinearLayout.LayoutParams(-2,-2));}line.addView(bubble,new LinearLayout.LayoutParams(-2,-2));messages.addView(line,new LinearLayout.LayoutParams(-1,-2));while(messages.getChildCount()>80)messages.removeViewAt(0);scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
 private MaterialButton icon(String name,String description,Runnable action){int resource=getResources().getIdentifier("assistant_ic_"+name,"drawable",getPackageName());MaterialButton b=new MaterialButton(this,null,com.google.android.material.R.attr.materialButtonOutlinedStyle);b.setText("");b.setStrokeWidth(0);b.setIconResource(resource);b.setIconSize(dp(23));b.setIconPadding(0);b.setIconGravity(MaterialButton.ICON_GRAVITY_TEXT_START);b.setIconTint(android.content.res.ColorStateList.valueOf(color(androidx.appcompat.R.attr.colorPrimary)));b.setContentDescription(description);b.setTooltipText(description);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(10),0,dp(10),0);b.setInsetTop(0);b.setInsetBottom(0);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(android.graphics.Color.TRANSPARENT));b.setOnClickListener(v->action.run());return b;}
 private void persist(){try{android.util.AtomicFile file=new android.util.AtomicFile(new File(getCacheDir(),"assistant-chat.json"));FileOutputStream out=null;try{out=file.startWrite();out.write(new JSONObject().put("history",new JSONArray(engine.snapshot())).put("transcript",transcript).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));file.finishWrite(out);}catch(Exception e){if(out!=null)file.failWrite(out);}}catch(Exception ignored){}}
 private void load(){try(InputStream in=new FileInputStream(new File(getCacheDir(),"assistant-chat.json"))){JSONObject saved=new JSONObject(ChatEngine.read(in));engine.restore(saved.getJSONArray("history").toString());JSONArray log=saved.getJSONArray("transcript");for(int i=Math.max(0,log.length()-80);i<log.length();i++){JSONObject r=log.getJSONObject(i);transcript.put(r);addBubble(r.optString("who"),r.optString("text"),r.optString("image"));}}catch(Exception ignored){}}
